// Packaging-line simulator. Ticks every second, publishes every PUBLISH_INTERVAL s.
const site = env.get('FACTORY_SITE') || 'demo';
const line = env.get('FACTORY_LINE') || 'line-1';
const interval = Math.max(1, parseInt(env.get('PUBLISH_INTERVAL') || '2', 10));
const now = Date.now();
if (now - (context.get('last') || 0) < interval * 1000 - 100) {
    return null;
}
context.set('last', now);

// Unattended booth mode: a random fault every 2-4 minutes, cleared after 2.
if (String(env.get('AUTO_CHAOS')).toLowerCase() === 'true') {
    const chaos = context.get('chaos') || { next: now + 60000, clearAt: 0 };
    if (chaos.clearAt && now >= chaos.clearAt) {
        global.set('faults', {});
        chaos.clearAt = 0;
        chaos.next = now + (120 + Math.random() * 120) * 1000;
        node.log('auto-chaos: faults cleared');
    } else if (!chaos.clearAt && now >= chaos.next) {
        const options = [['press-01', 'overheat'], ['cnc-02', 'bearing'], ['robot-03', 'jam']];
        const pick = options[Math.floor(Math.random() * options.length)];
        global.set('faults', { [pick[0]]: pick[1] });
        chaos.clearAt = now + 120000;
        node.log(`auto-chaos: ${pick[1]} on ${pick[0]}`);
    }
    context.set('chaos', chaos);
}

const MACHINES = global.get('machineDefs');
const STATE_CODE = { RUNNING: 0, DEGRADED: 1, STOPPED: 2, FAULT: 3 };
const faults = global.get('faults') || {};
const machines = global.get('machines') || {};
const approach = (cur, target, k) => cur + (target - cur) * k;
const noise = (amp) => (Math.random() - 0.5) * amp;
const round = (v, d) => Math.round(v * 10 ** d) / 10 ** d;
const msgs = [];

for (const [id, d] of Object.entries(MACHINES)) {
    const m = machines[id] || {
        temperature: d.temp, vibration: d.vib, rpm: d.rpm, power_kw: d.power,
        parts: 0, state: 'RUNNING'
    };
    const fault = faults[id] || 'none';

    // State machine. A trip (FAULT) latches until the fault is cleared.
    if (fault === 'none') {
        m.state = 'RUNNING';
    } else if (fault === 'jam') {
        m.state = 'STOPPED';
    } else if (m.state === 'FAULT' || m.temperature >= 95 || m.vibration >= 11) {
        m.state = 'FAULT';
    } else {
        m.state = 'DEGRADED';
    }

    let tT = d.temp, vT = d.vib, rT = d.rpm, pT = d.power, rate = d.rate;
    if (fault === 'overheat') { tT = d.temp + 50; pT = d.power * 1.3; }
    if (fault === 'bearing') { vT = d.vib + 12; tT = d.temp + 9; }
    if (m.state === 'STOPPED' || m.state === 'FAULT') { rT = 0; pT = d.power * 0.12; rate = 0; }

    // Slow ramps on the faulted signal so the audience can watch it climb.
    m.temperature = approach(m.temperature, tT, fault === 'overheat' ? 0.05 : 0.12) + noise(0.6);
    m.vibration = Math.max(0, approach(m.vibration, vT, fault === 'bearing' ? 0.05 : 0.2) + noise(0.3));
    m.rpm = Math.max(0, approach(m.rpm, rT, 0.4) + (rT ? noise(rT * 0.01) : 0));
    m.power_kw = Math.max(0, approach(m.power_kw, pT, 0.3) + noise(pT * 0.04));
    m.parts += rate * (interval / 60) * (0.9 + Math.random() * 0.2);

    let health = 100;
    health -= Math.max(0, m.temperature - (d.temp + 8)) * 1.6;
    health -= Math.max(0, m.vibration - (d.vib + 1.5)) * 6;
    if (m.state === 'STOPPED') health = Math.min(health, 25);
    if (m.state === 'FAULT') health = Math.min(health, 5);

    machines[id] = m;
    msgs.push({
        topic: `factory/${site}/${line}/${id}/telemetry`,
        payload: {
            ts: now, site, line, machine: id, type: d.type,
            state: m.state, state_code: STATE_CODE[m.state], fault,
            temperature: round(m.temperature, 1),
            vibration: round(m.vibration, 2),
            rpm: Math.round(m.rpm),
            power_kw: round(m.power_kw, 2),
            parts_total: Math.floor(m.parts),
            health: Math.round(Math.max(0, Math.min(100, health)))
        }
    });
}
global.set('machines', machines);

const bad = msgs.filter((x) => x.payload.state !== 'RUNNING');
node.status(bad.length
    ? { fill: 'red', shape: 'dot', text: bad.map((x) => `${x.payload.machine} ${x.payload.state}`).join(', ') }
    : { fill: 'green', shape: 'dot', text: `3 machines RUNNING, every ${interval}s` });
return [msgs];

