// and production rate (parts per minute).
global.set('machineDefs', {
    'press-01': { type: 'hydraulic_press', temp: 62, vib: 2.2, rpm: 30, power: 18, rate: 12 },
    'cnc-02': { type: 'cnc_mill', temp: 48, vib: 3.0, rpm: 9000, power: 11, rate: 4 },
    'robot-03': { type: 'packing_robot', temp: 41, vib: 1.4, rpm: 1500, power: 4.5, rate: 20 }
});
if (!global.get('faults')) global.set('faults', {});

