// factory/<site>/<line>/<machine>/cmd  payload {"fault":"overheat"} or "overheat"
const machine = msg.topic.split('/')[3];
msg.payload = (msg.payload && typeof msg.payload === 'object')
    ? Object.assign({ machine }, msg.payload)
    : { machine, fault: String(msg.payload) };
return msg;

// Accepts {machine, fault} from the inject buttons, MQTT commands and the REST API.
const FAULTS = ['overheat', 'bearing', 'jam', 'none'];
const MACHINES = Object.keys(global.get('machineDefs') || {});
let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = { fault: p }; }
}
p = p || {};
const machine = String(p.machine || msg.machine || 'all');
const fault = String(p.fault || 'none').toLowerCase();
const reply = (code, body) => {
    msg.statusCode = code;
    msg.payload = body;
    return msg.res ? [msg, null] : [null, msg];
};
if (!FAULTS.includes(fault) || !(machine === 'all' || MACHINES.includes(machine))) {
    node.warn(`rejected fault command machine=${machine} fault=${fault}`);
    return reply(400, {
        ok: false,
        error: `machine must be one of ${MACHINES.join(', ')} or all; fault must be one of ${FAULTS.join(', ')}`
    });
}
const faults = global.get('faults') || {};
for (const m of (machine === 'all' ? MACHINES : [machine])) {
    if (fault === 'none') delete faults[m]; else faults[m] = fault;
}
global.set('faults', faults);
const active = Object.entries(faults).map(([m, f]) => `${m}:${f}`);
node.status(active.length
    ? { fill: 'red', shape: 'ring', text: active.join(', ') }
    : { fill: 'green', shape: 'dot', text: 'no faults' });
node.log(`fault command: ${machine} -> ${fault}`);
return reply(200, { ok: true, faults });

msg.payload = {
    site: env.get('FACTORY_SITE'),
    line: env.get('FACTORY_LINE'),
    faults: global.get('faults') || {},
    machines: global.get('machines') || {},
    active_alerts: Object.values(global.get('activeAlerts') || {}),
    recent_alerts: global.get('recentAlerts') || []
};
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// Edge-triggered alert rules. Emits an alert when a rule's severity changes,
// and a 'resolved' event when it returns to normal.
const t = msg.payload;
if (!t || !t.machine) return null;
const RULES = [
    { rule: 'temperature', value: t.temperature, unit: 'C', warn: 85, crit: 95 },
    { rule: 'vibration', value: t.vibration, unit: 'mm/s', warn: 7, crit: 11 }
];
const levels = context.get('levels') || {};
const active = global.get('activeAlerts') || {};
const recent = global.get('recentAlerts') || [];
const out = [];

function emit(rule, severity, value, message, status) {
    const key = `${t.machine}/${rule}`;
    const alert = { ts: t.ts, site: t.site, line: t.line, machine: t.machine, rule, severity, value, message, status };
    if (status === 'active') active[key] = alert; else delete active[key];
    recent.unshift(alert);
    out.push(alert);
}

for (const r of RULES) {
    const level = r.value >= r.crit ? 'critical' : r.value >= r.warn ? 'warning' : 'ok';
    const key = `${t.machine}/${r.rule}`;
    const prev = levels[key] || 'ok';
    if (level !== prev) {
        if (level === 'ok') {
            emit(r.rule, 'info', r.value, `${t.machine} ${r.rule} back to normal (${r.value} ${r.unit})`, 'resolved');
        } else {
            const limit = level === 'critical' ? r.crit : r.warn;
            emit(r.rule, level, r.value, `${t.machine} ${r.rule} ${r.value} ${r.unit} above ${level} limit ${limit} ${r.unit}`, 'active');
        }
        levels[key] = level;
    }
}

const sKey = `${t.machine}/state`;
const prevState = levels[sKey] || 'RUNNING';
const stateNorm = t.state === 'DEGRADED' ? 'RUNNING' : t.state;
if (stateNorm !== prevState) {
    if (stateNorm === 'RUNNING') {
        emit('state', 'info', t.state_code, `${t.machine} running again`, 'resolved');
    } else {
        const sev = t.state === 'FAULT' ? 'critical' : 'warning';
        const why = t.state === 'FAULT' ? 'tripped on a safety limit' : `stopped (${t.fault})`;
        emit('state', sev, t.state_code, `${t.machine} ${why}`, 'active');
    }
    levels[sKey] = stateNorm;
}

context.set('levels', levels);
global.set('activeAlerts', active);
global.set('recentAlerts', recent.slice(0, 50));

const site = t.site, line = t.line;
const alertMsgs = out.map((a) => ({ topic: `factory/${site}/${line}/alerts`, payload: a }));
const toStore = [{ kind: 'telemetry', payload: t }].concat(out.map((a) => ({ kind: 'alert', payload: a })));
if (out.length) {
    const crit = out.filter((a) => a.severity === 'critical').length;
    node.status({ fill: crit ? 'red' : 'yellow', shape: 'dot', text: out[out.length - 1].message });
}
return [alertMsgs, toStore];

// Telemetry and alerts -> InfluxDB 2 line protocol (HTTP write API).
const tag = (s) => String(s).replace(/[ ,=]/g, '\\$&');
const str = (s) => '"' + String(s).replace(/["\\]/g, '\\$&') + '"';
const p = msg.payload;
let lp;
if (msg.kind === 'alert') {
    lp = `alerts,site=${tag(p.site)},line=${tag(p.line)},machine=${tag(p.machine)},rule=${tag(p.rule)},severity=${tag(p.severity)}`
        + ` message=${str(p.message)},status=${str(p.status)},value=${Number(p.value) || 0},active=${p.status === 'active' ? 1 : 0}i ${p.ts}`;
} else {
    lp = `machine_telemetry,site=${tag(p.site)},line=${tag(p.line)},machine=${tag(p.machine)},type=${tag(p.type)}`
        + ` temperature=${p.temperature},vibration=${p.vibration},rpm=${p.rpm}i,power_kw=${p.power_kw}`
        + `,parts_total=${p.parts_total}i,health=${p.health}i,state_code=${p.state_code}i`
        + `,state=${str(p.state)},fault=${str(p.fault)} ${p.ts}`;
}
const org = encodeURIComponent(env.get('INFLUX_ORG') || 'iot-factory');
const bucket = encodeURIComponent(env.get('INFLUX_BUCKET') || 'telemetry');
msg.method = 'POST';
msg.url = `http://influxdb:8086/api/v2/write?org=${org}&bucket=${bucket}&precision=ms`;
msg.headers = {
    Authorization: 'Token ' + global.get('influxToken'),
    'Content-Type': 'text/plain; charset=utf-8'
};
msg.payload = lp;
return msg;

// Count writes; report failures at most once a minute so the log stays readable.
const ok = msg.statusCode >= 200 && msg.statusCode < 300;
const s = context.get('stats') || { ok: 0, failed: 0, lastError: 0 };
if (ok) {
    s.ok += 1;
} else {
    s.failed += 1;
    if (Date.now() - s.lastError > 60000) {
        s.lastError = Date.now();
        node.error(`InfluxDB write failed (HTTP ${msg.statusCode || 'no response'}): ${String(msg.payload).slice(0, 200)}`, msg);
    }
}
context.set('stats', s);
node.status({ fill: s.failed ? 'red' : 'green', shape: 'dot', text: `written ${s.ok}, failed ${s.failed}` });
return null;
